package com.wms.controller; import com.wms.common.ApiResponse; import com.wms.dto.*; import com.wms.service.PurchaseRequestService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/purchase-requests") public class PurchaseRequestController { private final PurchaseRequestService service; public PurchaseRequestController(PurchaseRequestService s){service=s;} @GetMapping public ApiResponse<List<Map<String,Object>>> list(){return ApiResponse.ok(service.list());} @PostMapping public ApiResponse<Map<String,Object>> create(@Valid @RequestBody PurchaseRequestRequest r){return ApiResponse.ok("采购申请创建成功",service.create(r));}   @PostMapping("/{id}/review") @PreAuthorize("hasAuthority('purchase-request:review')") public ApiResponse<Map<String,Object>> review(@PathVariable Long id,@Valid @RequestBody ReviewRequest r){return ApiResponse.ok("审核完成",service.review(id,r));}  @PostMapping("/{id}/cancel") public ApiResponse<Map<String,Object>> cancel(@PathVariable Long id){return ApiResponse.ok("采购申请已取消",service.cancel(id));} }
